-- Resources content for the new excerpt level standard (CLAUDE.md, "Resources stay in step with the code").
-- Content only; no schema.

select private.rc_release_guide(
  p_slug => 'sourcework-transcript-and-excerpts',
  p_tool_key => 'transcription',
  p_title => 'Working with the transcript and creating excerpts',
  p_summary => 'Find your way in a transcript, name speakers, and save a stretch of it as an excerpt.',
  p_screen_keys => array['sourcework.project', 'sourcework.source'],
  p_sort_order => 15,
  p_version_note => 'Excerpts level to -18 LUFS with a -6 dBFS limiter',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The transcript is on the left and the project's excerpts for this source are on the right. Excerpts are short clips saved for reuse."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Find your way"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Find in this transcript","marks":[{"type":"bold"}]},{"type":"text","text":" looks for a word or phrase from two characters on. Matching words are highlighted. Select the arrows, or press Enter, to step through the matches."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The marks under the progress bar show where your excerpts are; select one to open it. With many excerpts the marks merge into a shaded strip, and darker means more excerpts there. Select a stretch of the strip to zoom the progress bar in until the excerpts separate into their own marks, and select "},{"type":"text","text":"Show the whole recording","marks":[{"type":"bold"}]},{"type":"text","text":" to zoom back out."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Speakers","marks":[{"type":"bold"}]},{"type":"text","text":" button names the speakers, with the first few names after it. It opens a list ordered by who spoke most. Type a name to rename a speaker, or select "},{"type":"text","text":"Hear an example","marks":[{"type":"bold"}]},{"type":"text","text":". From seven speakers a find box and an "},{"type":"text","text":"Unnamed only","marks":[{"type":"bold"}]},{"type":"text","text":" switch appear."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If the transcript split one person into two voices, select "},{"type":"text","text":"Merge…","marks":[{"type":"bold"}]},{"type":"text","text":" on the extra speaker and choose who it really was. All of its lines move to that speaker."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit a line"}]},{"type":"paragraph","content":[{"type":"text","text":"Select the ⋮ at the end of any line for "},{"type":"text","text":"Edit text","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"Change speaker…","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Merge with the next line","marks":[{"type":"bold"}]},{"type":"text","text":". Double-clicking the text, or pressing E on the current line, also starts an edit."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Edit a source's details"}]},{"type":"paragraph","content":[{"type":"text","text":"Select the ⋮ beside the source's title and choose "},{"type":"text","text":"Edit details","marks":[{"type":"bold"}]},{"type":"text","text":". A card opens above the transcript with the title and, for a recording, the date it was recorded. Select "},{"type":"text","text":"Save","marks":[{"type":"bold"}]},{"type":"text","text":" to keep the change; the source's search entries update with it. A PDF has a title only."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Create an excerpt"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Drag to select the stretch of text you want."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A bar opens at the bottom of the transcript with a title already filled in, and the time range beside it. The title starts as the first words you selected and, a moment later, is replaced by a short description of what the speaker says, if you haven't started typing. When you save, the excerpt is named in full: the project, then who is speaking, then your title, such as Hurricane Isaias_Chip Simmons_Second fatality from generator fumes. That is also the name of the file you download."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Change the title if you like, then press Enter or select "},{"type":"text","text":"Save excerpt","marks":[{"type":"bold"}]},{"type":"text","text":". "},{"type":"text","text":"Preview","marks":[{"type":"bold"}]},{"type":"text","text":" plays the exact range; Esc cancels."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Working with excerpts"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The panel lists this source's excerpts. "},{"type":"text","text":"In order","marks":[{"type":"bold"}]},{"type":"text","text":" follows the recording and "},{"type":"text","text":"Newest","marks":[{"type":"bold"}]},{"type":"text","text":" puts the latest first. From nine excerpts a filter box appears, and twenty show at a time with "},{"type":"text","text":"Show more","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The round "},{"type":"text","text":"play button","marks":[{"type":"bold"}]},{"type":"text","text":" on a card plays that excerpt. While it plays the button turns into a pause button, so you can stop it from the card without going to the player. Playing another excerpt switches to that one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Trim","marks":[{"type":"bold"}]},{"type":"text","text":" opens buttons to nudge the start or end of a clip by a small step or a larger one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Export WAV","marks":[{"type":"bold"}]},{"type":"text","text":" renders the clip to its own audio file; "},{"type":"text","text":"Download","marks":[{"type":"bold"}]},{"type":"text","text":" appears when it is ready."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Level","marks":[{"type":"bold"}]},{"type":"text","text":" line on a card shows the volume change applied to that excerpt, such as +4.2 dB. Every excerpt is measured when you create or trim it, then played and exported at a fixed level of -18 LUFS, the level the team preps actualities at in Audition, followed by a hard limiter that holds peaks at -6 dBFS. One actuality no longer comes in much hotter or quieter than the last. The level is one volume setting for the whole excerpt, so a speaker who drops to a whisper stays that far below their own normal voice; only the peaks are limited. Select "},{"type":"text","text":"Original level","marks":[{"type":"bold"}]},{"type":"text","text":" to play and export an excerpt as recorded, for example when the quiet is the point."},{"type":"text","text":" A card that says "},{"type":"text","text":"measuring…","marks":[{"type":"bold"}]},{"type":"text","text":" is still being measured and updates by itself in a few seconds. If it says the excerpt couldn’t be measured, it plays and exports as recorded."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Export excerpts (zip)","marks":[{"type":"bold"}]},{"type":"text","text":" in the project's header exports every excerpt in the project at once."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select a card's title to rename it. "},{"type":"text","text":"Delete","marks":[{"type":"bold"}]},{"type":"text","text":" asks you to confirm."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A PDF source works the same way, but you select a stretch of the extracted text instead of a time range."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Trimming a clip after it has been exported makes that export stale. Re-export before you rely on the download."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Line menus and the speaker list work on a tablet or phone too: nothing waits on hovering."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Level is never applied to the recording itself, only to playback and to exports. Very quiet field tape can need a boost of 35 to 45 dB. Past 20 dB the card notes that the boost raises the background noise along with the voice. If a clip is stereo with the voice in one channel only, the voice is played and exported on both sides. Re-export after changing an excerpt's level, since an earlier export keeps the level it was made at."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-12-sourcework-excerpt-level-18-lufs',
  p_tool_key => 'transcription',
  p_released_on => '2026-10-12',
  p_title => 'Sourcework: excerpts now level to -18 LUFS with a limiter',
  p_guide_slugs => array['sourcework-transcript-and-excerpts'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Excerpts played quiet next to the team's own work, so they now match how actualities are prepared in Audition: brought to -18 LUFS, then held under -6 dBFS by a hard limiter, in playback and in exported files. Very quiet field tape can take a large boost, and the card now says when that boost raises the background noise. A stereo clip with the voice on one side only is played and exported on both sides. Excerpts you already exported are cleared and render again at the new level the next time you export them."}]}]}$body$
);
